594	// --- day buckets ---------------------------------------------------------------
595	
596	// An empty day row — the shape every counter folds through. Only the CAPTURE-derived
597	// scalars are zeroed: those are answered by files this fold reads in full every run,
598	// so zero is a fact about the day. Every other day field is left ABSENT until a source
599	// that can answer it does, because a source that could not be read is unknown and a
600	// zero written for it would read as a quiet day.
601	const emptyDay = () => ({
602	  ...Object.fromEntries(CAPTURE_DAY_FIELDS.map((f) => [f, 0])),
603	  skillLoads: {},
604	  checks: {}, checkFindings: {}, tasks: {}, taskExec: {}, queue: {},
605	  tokensByModel: {}, prs: {}, taskCost: {}, parks: {},
606	});
607	
608	// An empty hour row. All four counters are zeroed: an hour inside the window with no
609	// runs in it genuinely had none — the run listing covers the whole window or the fold
610	// does not advance its watermark at all.
611	const emptyHour = () => ({ ...Object.fromEntries(USAGE_FIELDS.hour.map((f) => [f, 0])), taskExec: {} });
612	
613	function addLoads(into, from) {
614	  for (const [name, n] of Object.entries(from)) into[name] = (into[name] ?? 0) + n;
615	}
616	
617	// The check maps fold the same way skillLoads do — key-wise, zeros implicit — only
618	// with a fixed-shape counter object under each key instead of a bare number.
619	function addCounters(into, from) {
620	  for (const [key, row] of Object.entries(from ?? {})) {
621	    const target = (into[key] ??= Object.fromEntries(Object.keys(row).map((k) => [k, 0])));
622	    for (const [field, n] of Object.entries(row)) target[field] = (target[field] ?? 0) + n;
623	  }
624	}
625	
626	// Recompute the day rows from scratch, from the live capture files. `files` is
627	// `[{ date, issue, pr, sessionId, counts }]` — one entry per capture file in the raw
628	// window, `counts` being that file's `countEntries` result.
629	//
630	// Stateless by construction: a day is a pure function of the files stamped with it,
631	// so there is no ingest ledger, no double-count risk, and a counting-bug fix
632	// self-heals the entire visible window on its next run.
633	export function foldDays(files) {
634	  const days = {};
635	  const sessionsByDay = {};
636	  // The two PER-SESSION figures, which must not be summed over capture files: a
637	  // session that captured twice (a merge, then the session-end tail) writes the same
638	  // facts into both files, and the second is usually a superset of the first. So they
639	  // are collected per (day, session) and reduced at the end — the largest token spend
640	  // any of the session's captures attests.
641	  const perSession = {};
642	  const blankSession = () => ({
643	    tokens: null, tokensByModel: null,
644	    seconds: null, task: null, userMessages: 0,
645	  });
646	  const session = (date, id) => ((perSession[date] ??= new Map()).get(id)
647	    ?? (perSession[date].set(id, blankSession()), perSession[date].get(id)));
648	
649	  for (const file of files) {
650	    const day = (days[file.date] ??= emptyDay());
651	    day.captures += 1;
652	    // A capture keyed to a PR or an issue has work behind it; issue 0 is a tail
653	    // capture with no merge behind it.
654	    if (file.pr > 0 || file.issue > 0) day.merges += 1;
655	    day.userMessages += file.counts.userMessages;
656	    day.userCommands += file.counts.userCommands;
657	    addLoads(day.skillLoads, file.counts.skillLoads);
658	    addCounters(day.checks, file.counts.checks);
659	    addCounters(day.checkFindings, file.counts.checkFindings);
660	    addCounters(day.taskExec, file.counts.taskExec);
661	    (sessionsByDay[file.date] ??= new Set()).add(file.sessionId);
662	
663	    const s = session(file.date, file.sessionId);
664	    const t = file.counts.tokens;
665	    // The per-model split rides the SAME winning capture as the total it splits, so
666	    // the two can never describe different captures of one session.
667	    if (t && (s.tokens === null || t.input + t.output > s.tokens.input + s.tokens.output)) {
668	      s.tokens = t;
669	      s.tokensByModel = file.counts.tokensByModel ?? null;
670	    }
671	    const secs = file.counts.seconds;
672	    if (secs && (s.seconds === null || secs.human + secs.agent > s.seconds.human + s.seconds.agent)) {
673	      s.seconds = secs;
674	    }
675	    // The task the session belongs to, resolved ACROSS its captures rather than per
676	    // capture: a session has one dispatch, but its captures disagree about the evidence
677	    // — the tail capture is filed under issue 0 where the merge capture named the PR,
678	    // and a capture written mid-run can predate the execution record the tail
679	    // carries. So the most-informed answer any of them gives wins.
680	    const key = taskCostKey(file.counts, file.pr ?? file.issue);
681	    if (taskCostRank(key) > taskCostRank(s.task)) s.task = key;
682	    // Summed over the session's captures rather than deduped, so the per-task column
683	    // adds up to the day's own `userMessages` scalar, which is summed the same way.
684	    s.userMessages += file.counts.userMessages;
685	  }
686	
687	  // Distinct sessions, not capture count: one session can capture more than once
688	  // (a merge, then the session-end tail).
689	  for (const [date, set] of Object.entries(sessionsByDay)) days[date].sessions = set.size;
690	
691	  for (const [date, bySession] of Object.entries(perSession)) {
692	    const day = days[date];
693	    for (const { tokens, tokensByModel, seconds, task, userMessages } of bySession.values()) {
694	      // Absent until one session on this day attested a spend — the fields stay off
695	      // the row entirely on a day whose transcripts carried no usage records, which is
696	      // what makes "this shape does not record it" distinguishable from "it was free".
697	      if (tokens) {
698	        day.tokensIn = (day.tokensIn ?? 0) + tokens.input;
699	        day.tokensOut = (day.tokensOut ?? 0) + tokens.output;
700	        day.tokenSessions = (day.tokenSessions ?? 0) + 1;
701	      }
702	      if (tokensByModel) addCounters(day.tokensByModel, tokensByModel);
703	      // Same absence rule for the two wall-clock scalars: a day whose sessions carried
704	      // no entry timestamps keeps no key rather than reporting nobody worked.
705	      if (seconds) {
706	        day.humanSeconds = (day.humanSeconds ?? 0) + seconds.human;
707	        day.agentSeconds = (day.agentSeconds ?? 0) + seconds.agent;
708	      }
709	      // `sessions` and `userMessages` are counted off the capture files and are always
710	      // real; the two token columns stay ABSENT until a session of this task attested a
711	      // spend, so a task whose transcripts record no usage reads as unknown rather than
712	      // as having run for free.
713	      const cost = (day.taskCost[task] ??= { sessions: 0, userMessages: 0 });
714	      cost.sessions += 1;
715	      cost.userMessages += userMessages;
716	      if (tokens) {
717	        cost.tokensIn = (cost.tokensIn ?? 0) + tokens.input;
718	        cost.tokensOut = (cost.tokensOut ?? 0) + tokens.output;
719	      }
720	    }
721	  }
722	  return days;
723	}
