725	// --- the sources outside the capture files ----------------------------------------
726	
727	// Merge a day-keyed map of already-computed fields into the day rows — the shape both
728	// the local-git series (commits and lines) and the releases listing arrive in. A day
729	// the source could not speak for is simply absent from `bySource` and keeps no key,
730	// which is the whole point of doing this outside `emptyDay`.
731	export function foldDayFields(days, bySource = {}) {
732	  for (const [date, fields] of Object.entries(bySource)) {
733	    const day = (days[date] ??= emptyDay());
734	    for (const [field, value] of Object.entries(fields)) {
735	      if (typeof value === 'number' && Number.isFinite(value)) day[field] = value;
736	    }
737	  }
738	  return days;
739	}
