741	// The queue's own record of what each occurrence came to: closed work items, per task,
742	// per outcome word. APPEND-ONCE past `queueFoldedThrough`, for the same reason the run
743	// ledger is — the items are a paged REST read where the capture files are local git —
744	// and safe to append because a closed item is settled: its outcome label is written at
745	// convergence and nothing later moves it.
746	//
747	// `records` is `[{ date, pack, task, outcome, parks }]`, already filtered by the reader
748	// to items that closed past the mark. `parks` is the kinds the item was parked for at
749	// any point in its life, each counted ONCE for it — an item bounced between a person
750	// and the machine twice is one park of that kind, not two — or `null` where the item's
751	// event listing could not be read, which costs its parks and not its outcome.
752	// @deprecated The `queue` and `parks` rows have a successor:
753	// `.claudinite/local/tasks-usage.GENERATED.json`, which counts the same outcomes and
754	// the same parks beside the latencies and costs they belong with
755	// (`packs/claudinite-tasks/tasks/tasks-usage-fold/README.md`). This writer keeps
756	// running — the rows it has already written are real and its readers still read them
757	// — and retiring it is a later plan of its own rather than a window this one closes.
758	export function foldQueueOutcomes(days, priorDays = {}, records = [], today) {
759	  for (const [date, row] of Object.entries(priorDays)) {
760	    if (!withinTaskWindow(date, today, DAY_WINDOW_DAYS)) continue;
761	    for (const group of ['queue', 'parks']) {
762	      const prior = row?.[group];
763	      if (!prior || !Object.keys(prior).length) continue;
764	      (days[date] ??= emptyDay())[group] = structuredClone(prior);
765	    }
766	  }
767	  for (const { date, pack, task, outcome, parks } of records) {
768	    const day = (days[date] ??= emptyDay());
769	    const id = `${pack}/${task}`;
770	    if (QUEUE_OUTCOMES.includes(outcome)) {
771	      const row = (day.queue[id] ??= Object.fromEntries(QUEUE_OUTCOMES.map((o) => [o, 0])));
772	      row[outcome] += 1;
773	    }
774	    if (!Array.isArray(parks)) continue;
775	    const row = (day.parks[id] ??= Object.fromEntries(USAGE_FIELDS.parks.map((k) => [k, 0])));
776	    for (const kind of new Set(parks)) if (kind in row) row[kind] += 1;
777	  }
778	  return days;
779	}
