781	// --- merged pull requests ---------------------------------------------------------
782	
783	// What each merged PR took, filed under the day it merged. APPEND-ONCE past
784	// `prsFoldedThrough` for the reason the queue read is: a paged REST resource where the
785	// capture files are local git, and a merge is settled — `merged_at` never moves.
786	//
787	// The rows carry DURATIONS, never percentiles: a week's p50 is not the mean of its
788	// days' p50s, so the quantile is the reader's reduction over whatever window it draws
789	// and the fold's job is to carry the sample. `merged` is the key count.
790	//
791	// `records` is `[{ date, number, leadHours, issueLeadHours, sessionToMergeHours }]`; a
792	// slot whose far end is unknown is `null` and keeps no key, which is not a zero lead.
793	export function foldPrs(days, priorDays = {}, records = [], today) {
794	  for (const [date, row] of Object.entries(priorDays)) {
795	    const prior = row?.prs;
796	    if (!prior || !Object.keys(prior).length || !withinTaskWindow(date, today, DAY_WINDOW_DAYS)) continue;
797	    (days[date] ??= emptyDay()).prs = structuredClone(prior);
798	  }
799	  for (const { date, number, ...hours } of records) {
800	    const day = (days[date] ??= emptyDay());
801	    const row = {};
802	    for (const field of USAGE_FIELDS.prs) {
803	      if (typeof hours[field] === 'number' && Number.isFinite(hours[field])) row[field] = hours[field];
804	    }
805	    day.prs[String(number)] = row;
806	  }
807	  return days;
808	}
