810	// --- the hour tier ----------------------------------------------------------------
811	
812	// How long an hour row lives. Three days: long enough for the two-day view the
813	// dashboard draws plus a fold outage, short enough that the tier stays a few dozen
814	// rows rather than a log.
815	export const HOUR_WINDOW_HOURS = 72;
816	
817	export const withinHourWindow = (key, nowIso, hours = HOUR_WINDOW_HOURS) => {
818	  const age = (new Date(`${String(nowIso).slice(0, 13)}:00:00Z`) - new Date(`${key}:00:00Z`)) / 3600000;
819	  return Number.isFinite(age) && age >= 0 && age < hours;
820	};
821	
822	// The hour rows for this run. Two sources meeting in one row, and they are kept in
823	// separate FIELDS rather than merged, because they are trued up on different clocks:
824	//
825	//   - the run counts (`scheduler`, `executor`, `failed`) are APPENDED from the runs
826	//     read past the watermark, so prior rows carry forward and are added to;
827	//   - the capture-derived counts (`agentic`, and the per-task executions behind the
828	//     hover) are RECOMPUTED from the capture files every run, so they overwrite.
829	//
830	// Merging them into one counter would make the second source's recompute silently
831	// double the first's appended total.
832	export function foldHours({ prior = {}, runs = [], captureHours = {}, now }) {
833	  const hours = {};
834	  for (const [key, row] of Object.entries(prior)) {
835	    if (!withinHourWindow(key, now)) continue;
836	    hours[key] = { ...emptyHour(), ...structuredClone(row), taskExec: {} };
837	  }
838	  for (const run of runs) {
839	    const key = hourKey(run.startedAt);
840	    if (!withinHourWindow(key, now)) continue;
841	    const row = (hours[key] ??= emptyHour());
842	    if (run.workflow === 'scheduler') row.scheduler += 1;
843	    else if (run.workflow === 'executor') row.executor += 1;
844	    if (run.conclusion === 'failure' || run.conclusion === 'timed_out' || run.conclusion === 'startup_failure') {
845	      row.failed += 1;
846	    }
847	  }
848	  for (const [key, capture] of Object.entries(captureHours)) {
849	    if (!withinHourWindow(key, now)) continue;
850	    const row = (hours[key] ??= emptyHour());
851	    row.agentic = capture.agentic;
852	    row.taskExec = structuredClone(capture.taskExec ?? {});
853	  }
854	  return hours;
855	}
856	
857	// The capture files' own view of an hour: how many distinct sessions captured in it,
858	// and what they executed. The filename stamp is the clock — the same stamp the logs
859	// branch's retention rules read, machine-written by the capture step.
860	export function captureHours(files) {
861	  const out = {};
862	  const sessions = {};
863	  for (const file of files) {
864	    if (!file.stamp) continue;
865	    const key = hourKey(file.stamp);
866	    const row = (out[key] ??= { agentic: 0, taskExec: {} });
867	    (sessions[key] ??= new Set()).add(file.sessionId);
868	    addCounters(row.taskExec, file.counts.taskExec);
869	  }
870	  for (const [key, set] of Object.entries(sessions)) out[key].agentic = set.size;
871	  return out;
872	}
