874	// --- task invocations -----------------------------------------------------------
875	
876	// How long a task row stays in the DAY tier. Independent of the capture retention
877	// on purpose: these rows come from the scheduler's Actions logs, not from the logs
878	// branch, so nothing about them ages out when a capture file does — and a repo that
879	// captured nothing for a week must still show that its scheduled tasks ran. Past
880	// this, the day row goes and its week row carries it, exactly as the capture-derived
881	// days do.
882	export const TASK_DAY_WINDOW_DAYS = 14;
883	
884	// How long a day row lives at all. Wider than the task rows and wider than the capture
885	// retention, because the local-git and queue series reach further back than either and
886	// the growth panels read a month of them. A day past this drops out of the tier; its
887	// week row keeps what it held.
888	export const DAY_WINDOW_DAYS = 30;
889	
890	export function withinTaskWindow(date, today, days = TASK_DAY_WINDOW_DAYS) {
891	  const age = (new Date(`${today}T00:00:00Z`) - new Date(`${date}T00:00:00Z`)) / 86400000;
892	  return Number.isFinite(age) && age >= 0 && age < days;
893	}
894	
895	// Carry the slot scheduler's task-invocation rows forward while they are still inside
896	// the day window.
897	//
898	// HISTORY ONLY, WITH NO WRITER LEFT. These rows counted what the retired slot
899	// scheduler printed into its own Actions log about each due task; that writer is gone
900	// (#974) and its logs have aged out of retention, so nothing appends to them any more
901	// and the reader that did was retired with them rather than left to spend two API
902	// calls a run finding nothing. What each occurrence came to is read from the queue's
903	// own closed items now (`foldQueueOutcomes`), which is the record that replaced it.
904	//
905	// So this only ages them out: a day row keeps its `tasks` counts until it leaves the
906	// window, and the week rows that already froze them keep them forever.
907	export function carryTaskRuns(days, priorDays = {}, today) {
908	  for (const [date, row] of Object.entries(priorDays)) {
909	    const tasks = row?.tasks;
910	    if (!tasks || !Object.keys(tasks).length || !withinTaskWindow(date, today)) continue;
911	    (days[date] ??= emptyDay()).tasks = structuredClone(tasks);
912	  }
913	  return days;
914	}
