916	// --- week buckets --------------------------------------------------------------
917	
918	// The ISO-8601 week a UTC date falls in, `YYYY-Www`. ISO weeks start Monday and
919	// belong to the year containing their Thursday — computed, never approximated,
920	// because an off-by-one here would silently mis-file a whole week's row.
921	export function isoWeek(date) {
922	  const d = new Date(`${date}T00:00:00Z`);
923	  const day = (d.getUTCDay() + 6) % 7;                 // Mon=0 … Sun=6
924	  d.setUTCDate(d.getUTCDate() - day + 3);              // the week's Thursday
925	  const year = d.getUTCFullYear();
926	  const firstThursday = new Date(Date.UTC(year, 0, 4));
927	  const offset = (firstThursday.getUTCDay() + 6) % 7;
928	  firstThursday.setUTCDate(firstThursday.getUTCDate() - offset + 3);
929	  const week = 1 + Math.round((d - firstThursday) / (7 * 86400000));
930	  return `${year}-W${String(week).padStart(2, '0')}`;
931	}
932	
933	// The days to fold into weeks this run: every completed day strictly after the
934	// watermark and strictly before today, in order. Days close strictly in order, so a
935	// single monotone watermark is the WHOLE exactly-once mechanism — no ingest ledger.
936	// `today` is excluded because its capture files are still arriving.
937	export function daysToFold(days, foldedThrough, today) {
938	  return Object.keys(days)
939	    .filter((d) => d < today && (!foldedThrough || d > foldedThrough))
940	    .sort();
941	}
942	
943	// Add one day row into its week row, append-once. Weeks carry `days` — how many day
944	// rows they absorbed — so a fold outage longer than the raw retention window
945	// declares its own hole (`days: 5`) instead of silently under-reporting.
946	//
947	// `sessionDays` rather than `sessions`: every counter here sums exactly under
948	// folding EXCEPT a distinct-session count (a session spanning two days is distinct
949	// in each), so the week-level field is named for what it actually is — the sum of
950	// the day-level distinct counts — rather than claiming a precision folding cannot
951	// give.
952	// Every scalar add is `?? 0` on the WEEK side for the same reason the counter maps
953	// below default rather than crash: a week frozen before a field existed carries no key
954	// for it, and the field must start accumulating from the first day that has it instead
955	// of wedging the watermark or reading back as NaN.
956	export function addDayToWeek(week, day) {
957	  const w = week ?? { skillLoads: {}, checks: {}, checkFindings: {} };
958	  const add = (field, n) => { w[field] = (w[field] ?? 0) + n; };
959	  add('days', 1);
960	  // Every other week scalar is the sum of the day field of the same name — the two
961	  // exceptions are spelled once, in WEEK_FROM_DAY. Driven off the vocabulary rather
962	  // than a hand-written list so a field appended to both rows folds without a third
963	  // edit here, which is where a new counter would otherwise be silently dropped.
964	  //
965	  // A day with NO opinion on a field adds nothing rather than zero: a week that
966	  // absorbed five days of unreadable git history and two of readable must report the
967	  // two, not seven days' worth of understated lines.
968	  for (const field of USAGE_FIELDS.week) {
969	    if (field === 'days') continue;
970	    const value = day[WEEK_FROM_DAY[field] ?? field];
971	    if (typeof value === 'number' && Number.isFinite(value)) add(field, value);
972	  }
973	  // The bare maps a week row can carry, so a week frozen before one existed reads
974	  // back the same shape a fresh fold builds.
975	  for (const map of BARE_MAPS) w[map] ??= {};
976	  addLoads(w.skillLoads, day.skillLoads);
977	  // Every counter group folds key-wise, driven off the vocabulary rather than a
978	  // hand-written list here — which is where a newly appended group would otherwise be
979	  // silently dropped out of the week tier.
980	  //
981	  // A week frozen before a group existed carries no key for it: defaulted rather than
982	  // crashed, so the first fold after the group ships extends those weeks from the day
983	  // it closes forward instead of wedging the watermark behind them.
984	  //
985	  for (const group of COUNTER_GROUPS) addCounters((w[group] ??= {}), day[group]);
986	  return w;
987	}
