      "description": "What happens to the work item when a recovery path would re-execute it. Default `requeue`; `needs-human` for a genuinely one-shot side effect."
    },
    "invocation_endpoint": {
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
      "description": "A key in the repo's taskScheduler.agenticTaskInvocationEndpoints — never a URL — for a task needing reach an ordinary session in its repo does not have."
    },
    "code_work_required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "The repo Actions secret names the code-work phase needs configured — the phase that runs Action-side, where a secret exists. Never GITHUB_* or CLAUDINITE_*."
    },
    "required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "deprecated": true,
      "description": "The retired spelling of code_work_required_secrets; normalized at the door. Rename it."
    },
    "model_from_request": {
      "const": true,
      "description": "Reserved to the engine's built-in request task: run at the model the work item names."
    },
    "session_scope": {
      "type": "string",
      "enum": [
        "self",
        "fleet"
      ],
      "deprecated": true,
      "description": "Read by nothing since #974. Drop it; name an invocation_endpoint if the task needs wider reach."
    }
  }
}

1	// The PreToolUse verdict, three duties in this order (the runner in
2	// hook-runner.mjs writes it; nothing here exits or writes):
3	//  - a file tool (Edit, Write, NotebookEdit) aimed at a path one of an active
4	//    pack's skills names under `force-load-on-file-edits-paths` — or any tool
5	//    call one names under `force-load-on-tool-calls` — is blocked until the
6	//    session has loaded that skill, so the skill is read before the first edit
7	//    or call exists, not after a Stop-time finding has sent the agent back over
8	//    work done;
9	//  - the active packs' ACTION declarations (`scope: "action"`, `guardToolCalls` —
10	//    the vocabulary in engine/checks/helpers/pattern-rules.mjs) are judged
11	//    against the call about to run: a blocking finding denies it and hands the
12	//    agent the finding's text, an advisory one lets it run and injects the text
13	//    as context, so a bias is heard at the moment it applies. The context
14	//    carries no permissionDecision: `allow` would skip the permission prompt
15	//    for the call, and an advisory has no business approving anything. The
16	//    same declarations run again over the transcript at Stop, advisory
17	//    there whatever the severity — the record for a hook that never fired;
18	//  - a Bash command that deletes a remote branch is blocked (the delete-push
19	//    fails in this environment, so it can never succeed).
20	// Registered on every tool (the converge's PRETOOLUSE_MATCHER) — see
21	// bootstrap.md. A call no declaration names costs the cached context read
22	// (hook-context.mjs) and says nothing. A guard that cannot decide lets the call
23	// through: an unreadable declaration or registry is the mount self-test's
24	// finding, never a session wedged on tools.
25	import { isAbsolute, relative, resolve, sep } from 'node:path';
26	import { hooklog } from '../checks/helpers/hook-log.mjs';
27	import { applyGrace } from '../checks/helpers/findings.mjs';
28	import { guardFindings } from '../checks/helpers/pattern-rules.mjs';
29	import { missingSkillsFor, missingSkillsForCall } from '../pack_loader/path-scoped-skills.mjs';
30	import { hookContext, sessionReader, loadInstruction } from './hook-context.mjs';
31	
32	// The file a tool is about to write, repo-relative with forward slashes — or null
33	// when the tool names no file or the file is outside the project (nothing here
34	// scopes a path the repo does not own).
35	function targetPath(payload, projectRoot) {
36	  const input = payload.tool_input ?? {};
37	  const raw = payload.tool_name === 'NotebookEdit' ? input.notebook_path : input.file_path;
38	  if (typeof raw !== 'string' || !raw) return null;
39	  const abs = isAbsolute(raw) ? raw : resolve(projectRoot, raw);
40	  const rel = relative(projectRoot, abs);
41	  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return null;
42	  return rel.split(sep).join('/');
43	}
44	
45	const FILE_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit']);
46	const packsOf = (missing) => [...new Set(missing.map((d) => d.pack))].join(', ');
47	const namesOf = (missing) => missing.map((d) => `\`${d.skill}\``).join(' and ');
48	
49	function fileToolBlock(payload, projectRoot, ctx, session) {
50	  const path = targetPath(payload, projectRoot);
51	  if (!path || !ctx.scoped.length) return null;
52	  const missing = missingSkillsFor(path, ctx.scoped, session.loaded);
53	  if (!missing.length) return null;
54	  const names = missing.map((d) => d.skill);
55	  hooklog('PreToolUse', `done exit=2 skill-not-loaded ${path} needs ${names.join(',')}`);
56	  return {
57	    reason: 'skill-not-loaded',
58	    block: `Blocked: ${path} is edited only with the ${namesOf(missing)} skill loaded `
59	      + `(the ${packsOf(missing)} pack's skill forces itself for ${missing.map((d) => d.files).join(', ')}). `
60	      + `Load it first — ${loadInstruction(missing, projectRoot)} — then retry the edit.`,
61	  };
62	}
63	
64	// The tool-call triggers: a call a skill forces itself for is held until the
65	// skill is loaded, exactly as an edit under a scoped path is.
66	function toolCallTriggerBlock(call, projectRoot, ctx, session) {
67	  const declarations = ctx.triggered.filter((d) => d.kind === 'toolCall');
68	  if (!declarations.length) return null;
69	  const missing = missingSkillsForCall(call, declarations, session.loaded);
70	  if (!missing.length) return null;
71	  const names = missing.map((d) => d.skill);
72	  hooklog('PreToolUse', `done exit=2 skill-not-loaded-for-call ${call.name} needs ${names.join(',')}`);
73	  return {
74	    reason: 'skill-not-loaded-for-call',
75	    block: `Blocked: ${call.name} is called only with the ${namesOf(missing)} skill loaded `
76	      + `(the ${packsOf(missing)} pack's skill forces itself for ${missing.map((d) => d.source).join(', ')}). `
77	      + `Load it first — ${loadInstruction(missing, projectRoot)} — then retry the call.`,
78	  };
79	}
80	
81	// The action declarations judged against this call: a blocking finding is the
82	// block, advisory ones the context. Grace applies as at Stop: a blocking guard
83	// inside its `since` window advises.
84	function actionVerdict(call, ctx, session) {
85	  const rules = ctx.actionRules.filter((r) => ctx.overrides[r.id] !== 'off');
86	  if (!rules.length) return {};
87	  let findings = [];
88	  for (const rule of rules) {
89	    const countsCalls = (rule.spec?.guardToolCalls ?? []).some((a) => a.atMostPerSession !== undefined);
90	    let found;
91	    try { found = guardFindings(rule, call, countsCalls ? session.calls() : []); }
92	    catch (e) { hooklog('PreToolUse', `action-guard-failed ${rule.id} ${e?.message ?? e}`); continue; }
93	    const level = ctx.overrides[rule.id];
94	    findings.push(...found.map((f) => (level === 'advisory' || level === 'blocking' ? { ...f, severity: level } : f)));
95	  }
96	  findings = applyGrace(findings);
97	  const render = (f) => `${f.what}. ${f.why ? `${f.why}. ` : ''}Fix: ${f.fix}`;
98	  const blocking = findings.filter((f) => f.severity === 'blocking');
99	  if (blocking.length) {
100	    hooklog('PreToolUse', `done exit=2 action-guard ${blocking.map((f) => f.rule).join(',')}`);
101	    return { block: blocking.map((f) => `Blocked by ${f.rule}: ${render(f)}`).join('\n'), reason: 'action-guard' };
102	  }
103	  const advisory = findings.filter((f) => f.severity === 'advisory');
104	  if (!advisory.length) return {};
105	  hooklog('PreToolUse', `advisory action-guard ${advisory.map((f) => f.rule).join(',')}`);
106	  return { context: advisory.map((f) => `[claudinite ${f.rule}] ${render(f)}`).join('\n') };
107	}
108	
109	function remoteBranchDeleteBlock(input) {
110	  const cmd = typeof input?.command === 'string' ? input.command : '';
111	  const deletesRemoteBranch =
112	    /\bgit\s+push\b[^\n;&]*\s(--delete|-d)\s/.test(cmd) ||
113	    /\bgit\s+push\b[^\n;&]*\s\S+\s+:\S/.test(cmd);
114	  if (!deletesRemoteBranch) return null;
115	  // Log only the block — the interesting event. An allowed command every Bash
116	  // call would flood the log and drown the SessionStart signal it exists for.
117	  hooklog('PreToolUse', 'done exit=2 blocked-remote-branch-delete');
118	  return {
119	    reason: 'blocked-remote-branch-delete',
120	    block: 'Blocked: never delete a remote branch — a current environment bug makes the delete-push fail, so it cannot succeed. Leave the branch; it can be deleted from the GitHub UI if needed.',
121	  };
122	}
123	
124	export async function judge(payload) {
125	  if (typeof payload.tool_name !== 'string') return null;
126	  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
127	  const call = { name: payload.tool_name, input: payload.tool_input ?? {} };
128	  const session = sessionReader(payload.transcript_path);
129	  let context = '';
130	  try {
131	    const ctx = await hookContext(projectRoot, 'PreToolUse');
132	    const held = (FILE_TOOLS.has(call.name) && fileToolBlock(payload, projectRoot, ctx, session))
133	      || toolCallTriggerBlock(call, projectRoot, ctx, session);
134	    if (held) return held;
135	    const action = actionVerdict(call, ctx, session);
136	    if (action.block) return action;
137	    context = action.context ?? '';
138	  } catch (e) {
139	    hooklog('PreToolUse', `done exit=0 guard-failed ${e?.message ?? e}`);
140	  }
141	  if (call.name === 'Bash') {
142	    const del = remoteBranchDeleteBlock(call.input);
143	    if (del) return del;
144	  }
145	  return context ? { context } : null;
146	}
