1	// Path-scoped skills: every skill an active pack bundles that declares
2	// `force-load-on-file-edits-paths` under its frontmatter `metadata` (the files a
3	// file tool may touch only with the skill loaded), and the one question both
4	// readers ask of them —
5	// which of those skills does THIS path need that the session has not yet loaded.
6	// The PreToolUse hook (engine/hooks/pretooluse-command.mjs) asks it before a file
7	// tool runs, so the skill is loaded before the first edit exists; the
8	// `skill-loaded-before-editing` work rule asks it of the diff at Stop, which is what
9	// catches an edit the hook never saw (one made through Bash). One resolver, so the
10	// two cannot disagree about a pattern.
11	//
12	// Pattern grammar is the harness's (memory docs, "path-specific rules"): `**` spans
13	// directories, `*` and `?` stay inside one segment, `{a,b}` expands, everything
14	// else is literal, and a pattern is matched against the whole repo-relative path —
15	// so `wiki/**` is the tree and `**/packs/*/RULES.md` is that file at any depth.
16	import { join } from 'node:path';
17	import { skillMetadata } from './skill-frontmatter.mjs';
18	
19	const RE_SPECIALS = /[.+^${}()|[\]\\]/g;
20	
21	// `{a,b}` groups multiplied out, innermost first, so the matcher below never sees one.
22	export function expandBraces(glob) {
23	  const m = /\{([^{}]*)\}/.exec(glob);
24	  if (!m) return [glob];
25	  return m[1].split(',').flatMap((alt) => expandBraces(glob.slice(0, m.index) + alt + glob.slice(m.index + m[0].length)));
26	}
27	
28	function oneGlobToSource(glob) {
29	  let re = '';
30	  for (let i = 0; i < glob.length; i += 1) {
31	    const c = glob[i];
32	    if (c === '*' && glob[i + 1] === '*') {
33	      // `**/` — zero or more whole segments; a trailing `**` — anything at all.
34	      if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 2; } else { re += '.*'; i += 1; }
35	    } else if (c === '*') re += '[^/]*';
36	    else if (c === '?') re += '[^/]';
37	    else re += c.replace(RE_SPECIALS, '\\$&');
38	  }
39	  return re;
40	}
41	
42	export function globToRegExp(glob) {
43	  return new RegExp(`^(?:${expandBraces(glob).map(oneGlobToSource).join('|')})$`);
44	}
45	
46	// The scoped skills of the given packs, flattened: [{ pack, skill, dir, files, re }], one
47	// entry per pattern. Callers pass the ACTIVE packs — activation is the registry's
48	// call, not this module's — so an undeclared pack's skills bind nothing. Read off each
49	// pack's own `skills` list (the convention fills it from the directory), so a skill the
50	// manifest withholds is not scoped either.
51	export function pathScopedSkills(packs) {
52	  const out = [];
53	  for (const pack of packs ?? []) {
54	    if (!pack.dir) continue;
55	    for (const skill of pack.skills ?? []) {
56	      const dir = join(pack.dir, 'skills', skill);
57	      for (const files of skillMetadata(dir).forceLoadPaths) {
58	        out.push({ pack: pack.id, skill, dir, files, re: globToRegExp(files) });
59	      }
60	    }
61	  }
62	  return out;
63	}
64	
65	// The declarations `hit` admits whose skill is not among `loaded`, deduped by
66	// skill name — the reason to stop an action, or the empty list that lets it run.
67	// `loaded` may be the names or a function producing them: the function is called
68	// only once a declaration hits, so the transcript behind it is read only when a
69	// verdict actually depends on it.
70	function missing(declarations, loaded, hit) {
71	  let have = null;
72	  const seen = new Set();
73	  const out = [];
74	  for (const d of declarations) {
75	    if (!hit(d) || seen.has(d.skill)) continue;
76	    have ??= new Set((typeof loaded === 'function' ? loaded() : loaded) ?? []);
77	    if (have.has(d.skill)) continue;
78	    seen.add(d.skill);
79	    out.push(d);
80	  }
81	  return out;
82	}
83	
84	export const missingSkillsFor = (path, declarations, loaded) => missing(declarations, loaded, (d) => d.re.test(path));
85	
86	// The TRIGGERED skills of the given packs, the three moments beside the path
87	// one: [{ pack, skill, dir, kind: 'toolCall' | 'prompt' | 'toolResult', tool,
88	// pattern, source }], one entry per trigger, read off the same skill metadata.
89	export function triggeredSkills(packs) {
90	  const out = [];
91	  for (const pack of packs ?? []) {
92	    if (!pack.dir) continue;
93	    for (const skill of pack.skills ?? []) {
94	      const dir = join(pack.dir, 'skills', skill);
95	      const meta = skillMetadata(dir);
96	      for (const t of meta.toolCallTriggers ?? []) out.push({ pack: pack.id, skill, dir, kind: 'toolCall', tool: t.tool, field: t.field, pattern: t.pattern, source: t.source });
97	      for (const p of meta.promptTriggers ?? []) out.push({ pack: pack.id, skill, dir, kind: 'prompt', tool: null, pattern: p.re, source: p.source });
98	      for (const t of meta.toolResultTriggers ?? []) out.push({ pack: pack.id, skill, dir, kind: 'toolResult', tool: t.tool, field: t.field, pattern: t.pattern, source: t.source });
99	    }
100	  }
101	  return out;
102	}
103	
104	const namesTool = (d, name) => (d.tool instanceof RegExp ? d.tool.test(name) : d.tool === name);
105	const asText = (v) => (typeof v === 'string' ? v : JSON.stringify(v ?? {}));
106	// The text a trigger's regex reads: the named field of the input (a dot path),
107	// or the whole input as JSON when the trigger names none.
108	const subjectOf = (d, value) => {
109	  if (!d.field) return asText(value);
110	  const at = d.field.split('.').reduce((v, k) => (v && typeof v === 'object' ? v[k] : undefined), value);
111	  return at === undefined || at === null ? '' : asText(at);
112	};
113	
114	// A call ({ name, input }) about to run, or recorded: the tool-call triggers it
115	// hits whose skill the session has not loaded.
116	export const missingSkillsForCall = (call, declarations, loaded) => missing(declarations, loaded,
117	  (d) => d.kind === 'toolCall' && namesTool(d, call.name) && (!d.pattern || d.pattern.test(subjectOf(d, call.input))));
118	
119	// An owner prompt: the prompt triggers its text hits.
120	export const missingSkillsForPrompt = (text, declarations, loaded) => missing(declarations, loaded,
121	  (d) => d.kind === 'prompt' && d.pattern.test(text ?? ''));
122	
123	// A call's result: the result triggers it hits.
124	export const missingSkillsForResult = (call, output, declarations, loaded) => missing(declarations, loaded,
125	  (d) => d.kind === 'toolResult' && namesTool(d, call.name) && d.pattern.test(subjectOf(d, output)));
126

1	// What every per-call hook reads before it can judge anything: the project's
2	// declared packs and rule overrides, and — derived from the active packs — the
3	// skill triggers (path, tool-call, prompt, result) and the action declarations.
4	// One reader, so the PreToolUse, UserPromptSubmit and PostToolUse judges cannot
5	// disagree about which packs are active or what they declare; one cache, so a
6	// hook that runs on every tool call pays the registry load once per session
7	// rather than once per call (`hookContext` below), and one transcript reader,
8	// parsed only when a trigger actually names the call (`sessionReader`).
9	import { existsSync, readFileSync, statSync, mkdirSync, writeFileSync, renameSync, unlinkSync } from 'node:fs';
10	import { createHash } from 'node:crypto';
11	import { tmpdir } from 'node:os';
12	import { dirname, join, resolve } from 'node:path';
13	import { fileURLToPath } from 'node:url';
14	import { hooklog } from '../checks/helpers/hook-log.mjs';
15	import { parseEntries, sessionTranscriptPaths, skillLoads, toolCalls } from '../checks/helpers/session-transcript.mjs';
16	import { settingsPath } from '../settings-file.mjs';
17	
18	// This module lives at <corpus>/engine/hooks/ — the same root the mount hook
19	// resolves the registry from, so the canon runs it from its own tree.
20	export const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
21	
22	// The raw settings: the declared packs (what activates) and the per-rule
23	// overrides (off / advisory / blocking), project-wide and per pack entry.
24	export function readSettings(projectRoot) {
25	  const path = settingsPath(projectRoot);
26	  if (!existsSync(path)) return { packs: [], rules: {} };
27	  const raw = JSON.parse(readFileSync(path, 'utf8'));
28	  const rules = { ...(raw.rules ?? {}) };
29	  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
30	    if (entry && typeof entry === 'object') Object.assign(rules, entry.rules ?? {});
31	  }
32	  return { packs: Array.isArray(raw.packs) ? raw.packs : [], rules };
33	}
34	
35	export async function activePacks(projectRoot, declared) {
36	  const { loadPacks, isActive } = await import(join(corpusRoot, 'engine', 'pack_loader', 'pack-registry.mjs'));
37	  const packs = await loadPacks({ localRoot: projectRoot, session: true });
38	  return packs.filter((p) => isActive(p, { packs: declared }));
39	}
40	
41	export function transcriptEntries(transcriptPath) {
42	  if (!transcriptPath || !existsSync(transcriptPath)) return [];
43	  try { return parseEntries(readFileSync(transcriptPath, 'utf8')); } catch { return []; }
44	}
45	
46	export const loadedSkills = (transcriptPath) => skillLoads(sessionEntries(transcriptPath));
47	
48	// Every entry the session wrote, its subagents' streams included — a payload
49	// names the session file whichever agent is calling, so a guard reading that
50	// file alone sees neither a subagent's load nor its calls (session-transcript.mjs
51	// states the layout).
52	export const sessionEntries = (transcriptPath) =>
53	  sessionTranscriptPaths(transcriptPath).flatMap(transcriptEntries);
54	
55	// The session transcript, read at most once per hook run and only on demand:
56	// `loaded()` is the skill names the session has loaded, `calls()` its recorded
57	// tool calls. A trigger matcher takes `loaded` as a function, so a call no
58	// trigger names never parses the transcript at all — on a long session that
59	// parse is the largest single cost a hook has.
60	export function sessionReader(transcriptPath) {
61	  let entries = null;
62	  const read = () => (entries ??= sessionEntries(transcriptPath));
63	  return { loaded: () => skillLoads(read()), calls: () => toolCalls(read()) };
64	}
65	
66	// The one sentence every trigger's block or nudge ends with: how to load the
