90	export const CACHE_VERSION = 1;
91	
92	const ENGINE_INPUTS = [
93	  'engine/pack_loader/pack-registry.mjs', 'engine/pack_loader/pack-conventions.mjs',
94	  'engine/pack_loader/pack-schema.mjs', 'engine/pack_loader/skill-frontmatter.mjs',
95	  'engine/pack_loader/path-scoped-skills.mjs', 'engine/pack_loader/renamed-packs.mjs',
96	  'engine/checks/helpers/pattern-rules.mjs', 'engine/checks/run-active-pack-rules.mjs',
97	  'engine/hooks/hook-context.mjs',
98	];
