121	function readCache(file) {
122	  try {
123	    const raw = JSON.parse(readFileSync(file, 'utf8'), reviver);
124	    if (raw?.version !== CACHE_VERSION || !holds(raw.fingerprint)) return null;
125	    return raw.derived;
126	  } catch { return null; }
127	}
