129	function writeCache(file, record) {
130	  const tmp = `${file}.${process.pid}.tmp`;
131	  try {
132	    mkdirSync(dirname(file), { recursive: true });
133	    writeFileSync(tmp, JSON.stringify(record, replacer));
134	    renameSync(tmp, file);
135	  } catch {
136	    try { unlinkSync(tmp); } catch { /* nothing to clean */ }
137	  }
138	}
