140	async function derive(projectRoot, declared) {
141	  const engine = (rel) => import(join(corpusRoot, rel));
142	  const [{ loadPacks, isActive, localPacksDir }, { pathScopedSkills, triggeredSkills }, { packRules }] = await Promise.all([
143	    engine('engine/pack_loader/pack-registry.mjs'), engine('engine/pack_loader/path-scoped-skills.mjs'),
144	    engine('engine/checks/run-active-pack-rules.mjs'),
145	  ]);
146	  const packs = (await loadPacks({ localRoot: projectRoot, session: true })).filter((p) => isActive(p, { packs: declared }));
147	  const derived = {
148	    scoped: pathScopedSkills(packs),
149	    triggered: triggeredSkills(packs),
150	    actionRules: packRules(packs).filter((r) => r.scope === 'action'),
151	  };
152	  const inputs = [
153	    settingsPath(projectRoot), join(corpusRoot, 'packs'), localPacksDir(projectRoot),
154	    ...ENGINE_INPUTS.map((rel) => join(corpusRoot, rel)),
155	    ...packs.flatMap((p) => [
156	      p.dir, join(p.dir, 'pack.mjs'), join(p.dir, 'declared-checks.json'), join(p.dir, 'skills'),
157	      ...(p.skills ?? []).flatMap((s) => [join(p.dir, 'skills', s), join(p.dir, 'skills', s, 'SKILL.md'), join(p.dir, 'skills', s, 'declared-checks.json')]),
158	    ]),
159	  ];
160	  return { derived, fingerprint: inputs.map(stamp) };
161	}
162	
163	export async function hookContext(projectRoot, event = 'hook') {
164	  const { packs: declared, rules: overrides } = readSettings(projectRoot);
165	  const file = cacheFile(projectRoot);
166	  const cached = readCache(file);
167	  if (cached) return { ...cached, overrides, source: 'cache' };
168	  const { derived, fingerprint } = await derive(projectRoot, declared);
169	  writeCache(file, { version: CACHE_VERSION, fingerprint, derived });
170	  hooklog(event, `registry-loaded ${derived.scoped.length} scoped, ${derived.triggered.length} triggered, ${derived.actionRules.length} action rules`);
171	  // The same shape the cache path returns: through the round trip, so the two
172	  // paths cannot differ by a field the serialisation drops.
173	  return { ...JSON.parse(JSON.stringify(derived, replacer), reviver), overrides, source: 'registry' };
174	}
