1	#!/usr/bin/env node
2	// SessionStart step: state, in one line, WHAT ACTUALLY LOADED this session —
3	// which repo, the active packs, the token weight of the prose injected, the guards
4	// and checks they arm, the skills mounted (the ones the hooks load on their own
5	// apart from the rest), plus whatever facet an active pack contributes about
6	// itself. Its stdout becomes session context, and it carries the directive that
7	// makes the session open with the line, so the person in front of it sees the
8	// load stated back rather than having to trust that it happened.
9	//
10	// WHY IT IS NOT THE ORCHESTRATOR'S FOOTER. That footer reports the MACHINERY:
11	// which steps ran and which crashed. This reports the VOLUME: how much guidance
12	// is in the window and how much of it is armed as checks. The two answer
13	// different questions and neither substitutes for the other — a session where
14	// every step ran and nothing was declared looks identical from the footer alone.
15	//
16	// RUNS LAST, after the steps whose work it counts (the skill mount), so it describes
17	// the session that exists rather than the one about to. The prose it weighs no longer
18	// arrives through this hook at all — it rides CLAUDE.md since #807 — but the weight is
19	// still this line's to state, because the cost lands in the same context window and a
20	// session that cannot see it has no way to notice the corpus growing.
21	//
22	// Core names no pack to get a pack-specific facet. A pack that has one states it
23	// on the FACET CHANNEL — a `CLAUDINITE-FACET:` line from its session-start step,
24	// collected by the step runner (engine/pack_loader/run-pack-session-start.mjs)
25	// into the file `CLAUDINITE_SESSION_FACETS` names — and this step appends what it
26	// finds there. The channel rides the step because the facts worth stating are the
27	// ones a pack had to COMPUTE: a static count is already in prose the reader has.
28	//
29	// Fails soft to silence, and exits 0 always — a non-zero exit makes Claude Code
30	// DISCARD the orchestrator's whole stdout, including the steps that did work.
31	import { readFileSync, existsSync } from 'node:fs';
32	import { join, dirname } from 'node:path';
33	import { fileURLToPath } from 'node:url';
34	import { settingsPath } from '../settings-file.mjs';
35	
36	import { spawnSync } from 'node:child_process';
37	
38	// The prose is reported in TOKENS because that is the unit of the cost it
39	// imposes — a context window, not a disk. The estimate goes through WORDS at the
40	// standard English ratio of roughly 0.75 words per token: prose is words, and a
41	// character count is thrown off by exactly what this corpus is full of — code
42	// fences, paths, punctuation-dense Markdown. Rounded to the hundred and shown in
43	// thousands (`14.3k`), because a session summary is a sense of scale, not an
44	// accounting.
45	const WORDS_PER_TOKEN = 0.75;
46	const TOKEN_ROUNDING = 100;
47	const plural = (n, one, many = `${one}s`) => `${n.toLocaleString('en-US')} ${n === 1 ? one : many}`;
48	const thousands = (n) => (n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n));
49	
50	// Which repo this is, as `owner/repo`: the checkout's own origin remote, or the
51	// Actions environment naming it. Neither known is no facet — the line never guesses
52	// a name, and a directory name is not one.
53	function repoName(projectRoot) {
54	  const fromEnv = process.env.GITHUB_REPOSITORY;
55	  const git = spawnSync('git', ['remote', 'get-url', 'origin'], { cwd: projectRoot, encoding: 'utf8' });
56	  const url = git.status === 0 ? git.stdout.trim() : '';
57	  const m = /[:/]([^/:]+)\/([^/]+?)(?:\.git)?\/?$/.exec(url);
58	  if (m) return `${m[1]}/${m[2]}`;
59	  return typeof fromEnv === 'string' && fromEnv.includes('/') ? fromEnv : null;
60	}
61	
62	try {
63	  const loaderDir = dirname(fileURLToPath(import.meta.url)); // <corpus>/engine/pack_loader
64	  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
65	
66	  let declared = [];
67	  const configPath = settingsPath(projectRoot);
68	  if (existsSync(configPath)) {
69	    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
70	    if (Array.isArray(raw.packs)) declared = raw.packs;
71	  }
72	
73	  const { loadPacks, isActive, bundledSkillSources } = await import(join(loaderDir, 'pack-registry.mjs'));
74	  const packs = await loadPacks({ localRoot: projectRoot, session: true });
75	  // A pack COPIED for the person in this session is left out of every count here. What it
76	  // loaded is already stated, by the step that copied it, on the facet channel this line
77	  // folds in - counting it again would state one set of rules twice, under two names.
78	  const active = packs.filter((pack) => isActive(pack, { packs: declared }) && !pack.temp);
79	  // Nothing active means this repo runs no Claudinite. Nothing loaded, so there
80	  // is nothing to state — the same silence the prose injector keeps.
81	  if (!active.length) process.exit(0);
82	
83	  // The prose the injector actually emits: each active pack's own file, resolved
84	  // off the pack's directory, trimmed the way the injector trims it. The routing
85	  // table and the directory pointer are the injector's framing rather than a
86	  // pack's rules, so they are not counted here.
87	  const wordsByPack = new Map();
88	  for (const pack of active) {
89	    if (!pack.prose) continue;
90	    const prosePath = join(pack.dir, pack.prose);
91	    if (!existsSync(prosePath)) continue;
92	    try {
93	      const words = readFileSync(prosePath, 'utf8').trim().split(/\s+/).filter(Boolean).length;
94	      wordsByPack.set(pack.id, (wordsByPack.get(pack.id) ?? 0) + words);
95	    } catch { /* an unreadable file counts as none */ }
96	  }
97	  const proseWords = [...wordsByPack.values()].reduce((n, w) => n + w, 0);
98	  const estimate = (words, rounding) => Math.round(words / WORDS_PER_TOKEN / rounding) * rounding;
99	  const tokens = estimate(proseWords, TOKEN_ROUNDING);
100	
101	  // What the active packs arm, split by WHEN it judges: a GUARD is a `scope: "action"`
102	  // declaration (`guardToolCalls`), judged per tool call by the PreToolUse hook; every
103	  // other rule — coded or declared, the pack's own or a skill's — is a CODE CHECK that
104	  // check_the_world and check_the_work between them run against this repo.
105	  let guards = 0;
106	  let checks = 0;
107	  for (const pack of active) {
108	    for (const rule of [...(pack.rules ?? []), ...(pack.skillChecks ?? [])]) {
109	      if (rule?.spec?.scope === 'action') guards += 1;
110	      else checks += 1;
111	    }
112	  }
113	
114	  // The mounted skills, split by HOW they load: an AUTO-TRIGGER skill carries a
115	  // `force-load-on-*` trigger, so a hook loads it deterministically at the moment it
116	  // names; a REGULAR skill is offered on its description and loaded on judgment.
117	  const { skillMetadata } = await import(join(loaderDir, 'skill-frontmatter.mjs'));
118	  let autoTrigger = 0;
119	  let regular = 0;
120	  for (const dir of bundledSkillSources(active).values()) {
121	    const m = skillMetadata(dir);
122	    const triggers = m.forceLoadPaths.length + m.toolCallTriggers.length + m.promptTriggers.length + m.toolResultTriggers.length;
123	    if (triggers > 0) autoTrigger += 1;
124	    else regular += 1;
125	  }
126	
127	  const facets = [
128	    plural(active.length, 'pack'),
129	    `${thousands(tokens)} context tokens`,
130	    plural(guards, 'guard'),
131	    plural(checks, 'code check'),
132	    plural(autoTrigger, 'auto-trigger skill'),
133	    plural(regular, 'regular skill'),
134	  ];
135	
136	  // Whatever the active packs' steps said about themselves, in the order the
137	  // runner ran them. Absent file, unreadable file, no channel at all: the engine
138	  // facets stand on their own.
139	  const facetsFile = process.env.CLAUDINITE_SESSION_FACETS;
140	  if (facetsFile && existsSync(facetsFile)) {
141	    try {
142	      for (const line of readFileSync(facetsFile, 'utf8').split('\n')) {
143	        if (line.trim()) facets.push(line.trim());
144	      }
145	    } catch { /* one unreadable channel is not the session's problem */ }
146	  }
147	
148	  // The directive comes FIRST and the line it names comes last, quoted by the colon:
149	  // a reader picking the nearest line then picks the summary. Said the other way round,
150	  // with the summary above and a "repeat that line" below it, the nearest line is the
151	  // directive itself — and sessions duly opened their replies by reciting it.
152	  //
153	  // It also has to say that the reply CONTINUES. A directive naming only what a reply
154	  // opens with is satisfiable by a reply that is nothing but its opening, and a first
155	  // turn answering to two such directives — this one and the `Comment class:` line —
156	  // has ended right there, both obligations discharged and no work done.
157	  const repo = repoName(projectRoot);
158	  process.stdout.write(
159	    'SESSION-START SUMMARY — an instruction to you, not text to repeat. '
160	    + 'Open your first reply of this session with exactly this line, and nothing before it. '
161	    + 'It prefixes that reply and is never the whole of it: the same turn goes on to answer '
162	    + 'the owner and act on what they asked. The line:\n\n'
163	    + `Loaded Claudinite${repo ? ` from repo ${repo}` : ''}: ${facets.join(', ')}.\n`,
164	  );
165	} catch {
166	  // fail soft — a broken summary must never block a session
167	}
