    userMessages,
    userCommands,
    skillLoads,
    tokens: tokensIn(entries),
    tokensByModel: tokensByModelIn(entries),
    seconds: turnSeconds(entries),
    taskExec: countTaskExecs(entries),
    ...countChecks(entries),
