1	#!/usr/bin/env node
2	// The skills index: `.claudinite/claudinite-skills.GENERATED.md`, one readable table
3	// of every skill the repo's active packs bundle — canon and local alike — with what
4	// makes each one load: its description (the text the harness matches a session's
5	// activity against) and, for a path-scoped skill, the `force-load-on-file-edits-paths`
6	// its SKILL.md declares (the files the PreToolUse guard holds until it is loaded). The rules index beside
7	// it (generate-rules-index.mjs) is the channel a pack's PROSE reaches a session on;
8	// this one is a catalog for a reader — a person asking "which skill fires when", a
9	// session checking why an edit was held. It is not imported by CLAUDE.md: the harness
10	// already carries every mounted skill's description into the session prompt, and a
11	// second copy would spend context on what is there.
12	//
13	// Written by the same converge that writes the rules index, from the same registry
14	// answer (the union of the active packs' bundled skills, bundledSkillSources), so the
15	// two cannot name different pack sets.
16	import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
17	import { join, dirname } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { loadPacks, isActive, bundledSkillSources } from './pack-registry.mjs';
20	import { skillMetadata } from './skill-frontmatter.mjs';
21	import { settingsPath } from '../settings-file.mjs';
22	
23	export const SKILLS_INDEX_FILE = join('.claudinite', 'claudinite-skills.GENERATED.md');
24	
25	function declaredPacks(projectRoot) {
26	  const configPath = settingsPath(projectRoot);
27	  if (!existsSync(configPath)) return [];
28	  try {
29	    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
30	    return Array.isArray(raw.packs) ? raw.packs : [];
31	  } catch { return []; }
32	}
33	
34	// One row per mounted skill, in mount order (the registry's: canon packs before
35	// local, a shared name resolving to canon): { skill, pack, description, paths }.
36	export function skillRows(active) {
37	  const sources = bundledSkillSources(active);
38	  const rows = [];
39	  for (const [skill, dir] of sources) {
40	    const pack = active.find((p) => (p.skills ?? []).includes(skill) && dir.startsWith(join(p.dir, 'skills')));
41	    const meta = skillMetadata(dir);
42	    rows.push({ skill, pack: pack?.id ?? '', description: meta.description, paths: meta.forceLoadPaths });
43	  }
44	  return rows;
45	}
46	
47	const cell = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim();
48	
49	// The index as text. Path-scoped skills first — they are the rows the guard acts on —
50	// then the rest, each group alphabetical, so the file reads as "these files, then
51	// these activities".
52	export function renderSkillsIndex(rows) {
53	  if (!rows.length) return null;
54	  const scoped = rows.filter((r) => r.paths.length).sort((a, b) => a.skill.localeCompare(b.skill));
55	  const rest = rows.filter((r) => !r.paths.length).sort((a, b) => a.skill.localeCompare(b.skill));
56	  const lines = [
57	    '<!-- GENERATED — do not hand-edit; every converge rewrites it. Edit a skill\'s SKILL.md frontmatter. -->',
58	    '# Skills mounted here, and what loads each one',
59	    '',
60	    'A skill loads when the session\'s activity matches its description. A skill that names files',
61	    'under `force-load-on-file-edits-paths` is also forced for them: a file tool aimed there is held',
62	    'by the PreToolUse guard until the skill is loaded (the Skill tool, or a Read of its SKILL.md),',
63	    'and an edit made another way is caught at Stop.',
64	    '',
65	  ];
66	  if (scoped.length) {
67	    lines.push('## Before editing these files', '', '| Files | Skill | Pack | Loads when |', '|---|---|---|---|');
68	    for (const r of scoped) lines.push(`| ${r.paths.map((p) => `\`${cell(p)}\``).join(', ')} | \`${r.skill}\` | ${r.pack} | ${cell(r.description)} |`);
69	    lines.push('');
70	  }
71	  if (rest.length) {
72	    lines.push('## By activity', '', '| Skill | Pack | Loads when |', '|---|---|---|');
73	    for (const r of rest) lines.push(`| \`${r.skill}\` | ${r.pack} | ${cell(r.description)} |`);
74	    lines.push('');
75	  }
76	  return `${lines.join('\n')}`;
77	}
78	
79	export async function skillsIndexRows(projectRoot) {
80	  try {
81	    const packs = await loadPacks({ localRoot: projectRoot });
82	    return skillRows(packs.filter((pack) => isActive(pack, { packs: declaredPacks(projectRoot) })));
83	  } catch {
84	    return []; // fail soft — a broken loader must never block a converge
85	  }
86	}
87	
88	export const skillsIndexContent = async (projectRoot) => renderSkillsIndex(await skillsIndexRows(projectRoot));
89	
90	// Write the index if its content changed; a repo with no mounted skill leaves any
91	// existing file alone (its packs may simply not be vendored yet).
92	export async function writeSkillsIndex(projectRoot) {
93	  const content = await skillsIndexContent(projectRoot);
94	  if (content === null) return false;
95	  const path = join(projectRoot, SKILLS_INDEX_FILE);
96	  if (existsSync(path) && readFileSync(path, 'utf8') === content) return false;
97	  mkdirSync(dirname(path), { recursive: true });
98	  writeFileSync(path, content);
99	  return true;
100	}
101	
102	async function main() {
103	  const argv = process.argv.slice(2);
104	  const root = argv.find((a) => !a.startsWith('--')) || process.env.CLAUDE_PROJECT_DIR || process.cwd();
105	  if (argv.includes('--write')) {
106	    console.log(await writeSkillsIndex(root) ? `wrote ${SKILLS_INDEX_FILE}` : `${SKILLS_INDEX_FILE} already current`);
107	    return;
108	  }
109	  process.stdout.write((await skillsIndexContent(root)) ?? '');
110	}
111	
112	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
113	  main().catch((e) => { console.error(e); process.exit(1); });
114	}
