    const kv = /^(\s*)([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
    if (!kv) continue;
    const [, , key, rest] = kv;
    if (indent > 0 && top) {
      // A key inside the open top-level container turns it into a map.
      if (Array.isArray(out[top.key]) && !out[top.key].length) out[top.key] = {};
