24	// Fast path: nothing changed vs the base and the tree is clean → stay silent.
25	const status = git('status', '--porcelain');
26	let dirty = status.status === 0 && status.stdout.trim() !== '';
27	if (!dirty) {
28	  for (const ref of ['origin/main', 'origin/master', 'main', 'master']) {
29	    const mb = git('merge-base', 'HEAD', ref);
30	    if (mb.status !== 0) continue;
31	    dirty = git('rev-parse', 'HEAD').stdout.trim() !== mb.stdout.trim();
32	    break;
33	  }
34	}
35	if (!dirty) process.exit(0); // clean fast path — nothing ran, nothing to log
36	
37	// Claude Code passes the hook's input JSON on stdin; its transcript_path is what
38	// lets the conversation-surface rules see the session. A manual run (TTY, or no
39	// parseable input) simply runs without them — they self-skip on a null transcript.
40	let transcriptPath = null;
41	try {
42	  if (!process.stdin.isTTY) {
43	    const input = readFileSync(0, 'utf8');
44	    if (input.trim()) transcriptPath = JSON.parse(input).transcript_path ?? null;
45	  }
46	} catch { /* no usable hook input — conversation rules self-skip */ }
47	
48	hooklog('Stop', 'start checks');
49	const run = spawnSync(process.execPath, [workRunner, ...(transcriptPath ? ['--transcript', transcriptPath] : [])], {
50	  cwd: projectRoot, encoding: 'utf8',
51	});
52	// The runner's timing record is a measurement, not a finding. Lift it off stdout
53	// before anything reads the report: it goes to the hook log, where the usage
54	// review's fold reads it from the transcript, and the loop guard below hashes
55	// findings alone — a millisecond that moves every run would make every stop look
56	// like a new one, so the guard would never relent.
57	const reported = (run.stdout ?? '').trim().split('\n');
58	const timing = reported.find((line) => line.includes(TIMING_PREFIX)) ?? null;
59	if (timing) hooklog('Stop', timing.trim());
60	const output = reported.filter((line) => line !== timing).join('\n').trim();
61	if (run.status === 0) {
62	  if (output) console.log(output); // advisory findings, for the transcript
63	  hooklog('Stop', 'done exit=0 checks-passed');
64	  process.exit(0);
65	}
66	
67	// The runner itself failing to launch is not a real finding — but don't pass
68	// silently: surface it and still block, so a broken enforcement setup can't wave
69	// sessions through unnoticed. The loop guard below keeps a persistent failure
70	// from wedging the session.
71	const runnerFailed = Boolean(run.error) || typeof run.status !== 'number';
72	
73	// Self-limiting loop guard: after blocking twice on the *same* findings, let the
74	// stop through rather than trapping a session that can't converge.
75	const hash = createHash('sha256').update(output).digest('hex').slice(0, 16);
76	const stateFile = join(
77	  tmpdir(),
78	  `claudinite-stop-${createHash('sha256').update(projectRoot).digest('hex').slice(0, 12)}.json`
79	);
80	let state = { hash: '', count: 0 };
81	if (existsSync(stateFile)) {
82	  try { state = JSON.parse(readFileSync(stateFile, 'utf8')); } catch { /* stale state resets below */ }
83	}
84	const count = state.hash === hash ? state.count + 1 : 1;
85	writeFileSync(stateFile, JSON.stringify({ hash, count }));
86	if (count > 2) {
87	  console.log('claudinite checks: the same blocking findings survived 2 fix attempts — letting the stop through. Run `node ' + workRunner + '` to see them.');
88	  hooklog('Stop', 'done exit=0 loop-guard-relent');
89	  process.exit(0);
90	}
91	
92	process.stderr.write(
93	  runnerFailed
94	    ? `Claudinite checks could not run — the check runner failed to launch: ${run.error?.message || 'abnormal exit'}. Fix the runner before relying on Stop-hook enforcement.`
95	    : 'Claudinite conformance checks failed — fix these findings now, in this session:\n\n' + output + '\n'
96	);
97	hooklog('Stop', `done exit=2 ${runnerFailed ? 'runner-error' : 'blocking-findings'}`);
98	process.exit(2);

