// "this ran for an issue and named no record", which beats "nobody filed this at all".
export const taskCostRank = (key) =>
  (key === null || key === undefined ? 0 : key === TASK_COST_NONE ? 1 : key === TASK_COST_UNRESOLVED ? 2 : 3);

