    tokens: null, tokensByModel: null,
    seconds: null, task: null, userMessages: 0,
  });
  const session = (date, id) => ((perSession[date] ??= new Map()).get(id)
    ?? (perSession[date].set(id, blankSession()), perSession[date].get(id)));

  for (const file of files) {
    const day = (days[file.date] ??= emptyDay());
    day.captures += 1;
    // A capture keyed to a PR or an issue has work behind it; issue 0 is a tail
    // capture with no merge behind it.
    if (file.pr > 0 || file.issue > 0) day.merges += 1;
    day.userMessages += file.counts.userMessages;
    day.userCommands += file.counts.userCommands;
    addLoads(day.skillLoads, file.counts.skillLoads);
    addCounters(day.checks, file.counts.checks);
    addCounters(day.checkFindings, file.counts.checkFindings);
    addCounters(day.taskExec, file.counts.taskExec);
    (sessionsByDay[file.date] ??= new Set()).add(file.sessionId);

    const s = session(file.date, file.sessionId);
    const t = file.counts.tokens;
    // The per-model split rides the SAME winning capture as the total it splits, so
    // the two can never describe different captures of one session.
    if (t && (s.tokens === null || t.input + t.output > s.tokens.input + s.tokens.output)) {
      s.tokens = t;
      s.tokensByModel = file.counts.tokensByModel ?? null;
    }
    const secs = file.counts.seconds;
    if (secs && (s.seconds === null || secs.human + secs.agent > s.seconds.human + s.seconds.agent)) {
      s.seconds = secs;
    }
