// How one session USED the corpus: which skills loaded and what made them load,
// which guards fired, how many moments a triggered skill's declaration actually
// had, and what the checks cost. The other half of a capture file's counting —
// fold-usage.mjs counts what the session produced, this counts what the corpus
// did to it — and the record the usage review's rules are evaluated against.
//
// EVERY COUNTER HERE IS A FLOOR. The marks are the hooks' own `hooklog` lines,
// which reach the transcript because hooklog mirrors to stderr and the harness
// records it. A hook killed before it logged, or a line the harness dropped, is
// invisible, and the direction that leaves is under-counting — the same bound the
// check counters already state for themselves.
import { isUserMessage, commandName, skillToolLoads } from './fold-usage.mjs';

// Every string value anywhere in one entry, newline-joined — the haystack the
// hooks' own log lines are read out of. They arrive in several entry shapes (a
// meta user turn, a stop-hook summary, an attachment), and the model may quote
// one back, so the reader below dedupes on the line rather than trusting a shape.
export function entryText(value, out = []) {
  if (typeof value === 'string') out.push(value);
  else if (Array.isArray(value)) for (const v of value) entryText(v, out);
  else if (value && typeof value === 'object') for (const v of Object.values(value)) entryText(v, out);
  return out;
}

// A hooklog line — `<iso> run=<id> <hook>: <message>`, the format hook-log.mjs
// writes and session-start-command.sh mirrors. Deduped on the whole line: the
// timestamp is to the second and the run id is per hook execution, so two
