// Drive the real counting pass over the real captured sessions, to read back what
// the new counters actually find — the live corpus, not a fixture.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { countEntries, mountedCorpus } from '/home/user/Claudinite/packs/claudinite-tasks/tasks/usage-fold/fold-usage.mjs';

const root = '/home/user/Claudinite';
const git = (...a) => execFileSync('git', a, { cwd: root, encoding: 'utf8', maxBuffer: 1 << 30 });
const names = git('ls-tree', '-r', '--name-only', 'origin/conversation-logs').trim().split('\n');
const recent = names.slice(-25);
const config = JSON.parse(readFileSync(`${root}/.claudinite-settings.json`, 'utf8'));
const corpus = await mountedCorpus(root, config);
console.log('mounted skills:', corpus.mounted.size, '| declarations:', corpus.declarations.length,
  '| hits resolved:', Boolean(corpus.hits.call), '| ownerOf:', Boolean(corpus.ownerOf));

const total = {};
const bump = (group, key, by = 1) => { (total[group] ??= {}); total[group][key] = (total[group][key] ?? 0) + by; };
for (const name of recent) {
  const entries = git('show', `origin/conversation-logs:${name}`).split('\n')
    .filter(Boolean).map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  const c = countEntries(entries, corpus);
  for (const [skill, row] of Object.entries(c.skillLoadsBy)) {
    for (const [cause, n] of Object.entries(row)) if (n) bump('loadsBy', `${skill}:${cause}`, n);
  }
  for (const [k, n] of Object.entries(c.skillBlocks)) bump('blocks', k, n);
  for (const [k, n] of Object.entries(c.moments)) bump('moments', k, n);
  for (const [k, r] of Object.entries(c.guardFires)) bump('guards', k, r.blocking + r.advisory);
  for (const [k, r] of Object.entries(c.triggerFires)) bump('fires', `${k} ${r.fired}/${r.followed}`);
  for (const [k, r] of Object.entries(c.checkTiming)) bump('timing', k, r.runs);
  for (const [k, n] of Object.entries(c.toolCalls)) bump('tools', k, n);
  for (const [k, n] of Object.entries(c.skillCaught)) bump('caught', k, n);
}
for (const [group, rows] of Object.entries(total)) {
  const top = Object.entries(rows).sort((a, b) => b[1] - a[1]).slice(0, 8);
  console.log(`\n${group}:`, JSON.stringify(Object.fromEntries(top)));
}
EOF
