1	// What the review WRITES: the file's shape, the dashboard's values, and the pull
2	// request's body. Pure over the evaluation's result, so the whole of what a reader
3	// sees is testable without a repository, a token or a clock.
4	export const LASTING_DAYS = 14;
5	
6	// Where the review's two outputs land. Here rather than in the worker because the
7	// precondition reads the first one to decide whether there is anything new to
8	// review, and a precondition must not import the worker's delivery machinery to
9	// learn a path.
10	export const REVIEW_PATH = '.claudinite/local/usage-review.GENERATED.json';
11	export const DASHBOARD_PATH = '.claudinite/local/dashboard/claudinite-growth.GENERATED.json';
12	
13	// A finding's identity is the pair it is about, and nothing else — not the figures,
14	// which move every day, and not the sentence, which an author may reword. That is
15	// what lets `since` survive a rule's prose being improved.
16	export const findingKey = (finding) => `${finding.rule}\u0000${finding.subject}`;
17	
18	const byRuleThenSubject = (a, b) => a.rule.localeCompare(b.rule) || a.subject.localeCompare(b.subject);
19	
20	export const daysBetween = (from, to) =>
21	  Math.round((new Date(`${to}T00:00:00Z`) - new Date(`${from}T00:00:00Z`)) / 86400000);
22	
23	// The whole file. `notEvaluated` is as much of the answer as `findings`: *no
24	// findings* is a result only when nothing was skipped for want of a floor.
25	export function reviewFile({ record, findings, notEvaluated, unstated, skills, check, guard, today }) {
26	  return {
27	    generated: `${today}T00:00:00Z`,
28	    window: {
29	      from: record.window.from,
30	      to: record.window.to,
31	      daysCovered: record.window.daysCovered,
32	      previous: { from: record.previous.from, to: record.previous.to, daysCovered: record.previous.daysCovered },
33	      foldedThrough: record.foldedThrough,
34	      subjects: { skills: skills.length, checks: check.length, guards: guard.length },
35	      // How many rules the twin definition could not see a twin for. A reader
36	      // weighing `check-never-fires-with-prose-twin` needs this: the definition is
37	      // deliberately narrow, and a large number here is the definition's limit
38	      // showing rather than a fleet of twin-less checks.
39	      twinless: check.filter((c) => !c.proseTwin).length,
40	    },
41	    findings: [...findings].sort(byRuleThenSubject).map((f) => ({
42	      ...f,
