63	      note: `${file.window.from} to ${file.window.to}`,
64	    },
65	    'usage-newest': {
66	      rows: [...file.findings]
67	        .sort((a, b) => b.since.localeCompare(a.since) || a.subject.localeCompare(b.subject))
68	        .slice(0, 10)
69	        .map((f) => ({ subject: f.subject, rule: f.rule, cause: f.cause, since: f.since })),
70	    },
71	  };
72	}
