7	// rule to its file, how a pack's carriers are enumerated and which file each one
8	// names, and the two codemods that put a pack onto the convention (`markPack`,
9	// `convertReferences`). Every reader and writer of a `provenance/` folder composes
10	// this - the growth pack's checks and CLI, the migration-registry op that marks a
11	// member's local packs at converge - so the grammar is spelled once, here, and
12	// nothing below carries a rule's failure text or a command's wording (those are the
13	// callers'). The convention itself - what an element is, what an entry records, what
14	// is never vendored - is docs/provenance/DESIGN.md's; this module is what it says a
15	// file looks like.
16	//
17	// io is injected everywhere - `{ read, write, exists, listDir, remove? }` over
18	// repo-relative posix paths - so the same code runs over a checkout (the CLI) and
19	// inside the registry's record io (a member's converge) without a second
20	// implementation.
21	
22	export { PROVENANCE_DIR };
23	
24	// The pack's own file and the declined log, each sorted ahead of every element by
25	// the underscore. `_pack` is also the id the manifest names.
26	export const PACK_ELEMENT = '_pack';
27	export const DECLINED_FILE = '_declined.md';
28	
29	// The closed kind vocabulary, and the kinds whose entry always carries Mechanism.
30	export const KINDS = Object.freeze(['born', 'reworded', 'strengthened', 'weakened', 'split', 'merged', 'moved',
31	  'converted', 'trigger-changed', 'policy-changed', 'severity-changed', 'reaffirmed', 'promoted', 'retired']);
32	export const MECHANISM_KINDS = Object.freeze(['born', 'converted', 'moved', 'trigger-changed', 'policy-changed', 'severity-changed']);
33	export const FIELDS = Object.freeze(['Source', 'Reason', 'Actor', 'Model', 'Mechanism', 'Rejected', 'Retire when', 'Landed']);
34	export const DECLINED_KIND = 'declined';
35	
36	// A slug marker ends a rule's last line: two to four hyphenated words, so a plain
37	// parenthetical (`(canon)`, `(see below)`), an issue (`(#1119)`) and the retired
38	// numeric marker (`(3)`, `(3, 7)`) never read as one.
39	export const SLUG_RE = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/;
40	const MARKER_AT_END = /\s*\(([a-z][a-z0-9]*(?:-[a-z0-9]+)+)\)\s*$/;
41	// The numeric marker the references convention used - `(3)`, `(3, 7)`, `(2a)`, and the
42	// `(RULES-14)` spelling some rules took - read only so the conversion can replace it.
43	const NUMERIC_MARKER_AT_END = /\s*\((?:RULES-)?(\d+[a-z]?(?:\s*,\s*\d+[a-z]?)*)\)\s*$/;
44	
45	const RULE_BULLET = /^- \*\*/;
46	const TOP_BULLET = /^- /;
47	const NESTED_ITEM = /^\s+(?:[-*+]|\d+\.)\s/;
48	const HEADING = /^#{1,6}\s+/;
49	const NUMBERED_STEP = /^\d+\.\s/;
50	const ENTRY_HEAD = /^## (\d{4}-\d{2}-\d{2}) · ([a-z-]+) · (.+?)\s*$/;
51	const FIELD_LINE = /^- \*\*([A-Z][A-Za-z ]*?):\*\*\s*(.*)$/;
52	
53	// A check's id becomes a file name with its slash as a hyphen (`cer/x` → `cer-x.md`);
54	// every element file is its id and `.md`, the pack's own and the declined log leading
55	// with an underscore.
56	const ELEMENT_FILE = /^_?[a-z0-9]+(?:-[a-z0-9]+)*\.md$/;
57	export const elementIdOf = (id) => String(id).replace(/\//g, '-');
58	export const fileOfId = (id) => `${elementIdOf(id)}.md`;
59	export const idOfFile = (name) => name.replace(/\.md$/, '');
60	
61	// --- the file grammar --------------------------------------------------------------
62	
63	// Every entry of a provenance file, in file order, with its fields and the grammar
64	// faults found on the way. A file is its entries and nothing else: a header, front
65	// matter or prose outside an entry is a fault, since it is the one part of the file
66	// that invites editing. `kinds` is the vocabulary the file admits - the element
67	// kinds, or the declined log's one kind.
68	export function parseEntries(text, { kinds = KINDS } = {}) {
69	  const entries = [];
70	  const errors = [];
71	  const lines = String(text ?? '').split('\n');
72	  let current = null;
73	  let lastDate = '';
74	  lines.forEach((raw, i) => {
75	    const line = raw.replace(/\r$/, '');
76	    const n = i + 1;
77	    const head = ENTRY_HEAD.exec(line);
78	    if (head) {
79	      const [, date, kind, title] = head;
80	      if (!kinds.includes(kind)) errors.push({ line: n, what: `entry kind "${kind}" is not in the vocabulary` });
81	      if (Number.isNaN(Date.parse(`${date}T00:00:00Z`))) errors.push({ line: n, what: `entry date "${date}" is not a date` });
82	      else if (date < lastDate) errors.push({ line: n, what: `entry dated ${date} follows one dated ${lastDate}; entries are appended in date order` });
83	      lastDate = date > lastDate ? date : lastDate;
84	      current = { date, kind, title, line: n, fields: {}, order: [], last: null };
85	      entries.push(current);
86	      return;
87	    }
88	    if (line.startsWith('## ')) {
89	      errors.push({ line: n, what: 'entry heading does not read "## <YYYY-MM-DD> · <kind> · <one line>"' });
90	      current = null;
91	      return;
92	    }
93	    if (!line.trim()) return;
94	    if (!current) {
95	      errors.push({ line: n, what: 'text outside an entry - a file is its entries and nothing else' });
96	      return;
97	    }
98	    const field = FIELD_LINE.exec(line);
99	    if (field) {
100	      const [, name, value] = field;
101	      if (!FIELDS.includes(name)) errors.push({ line: n, what: `field "${name}" is not in the vocabulary (${FIELDS.join(', ')})` });
102	      if (!value.trim()) errors.push({ line: n, what: `field "${name}" is empty - a field with nothing behind it is omitted, never filled` });
103	      if (name in current.fields) errors.push({ line: n, what: `field "${name}" repeats within one entry` });
104	      current.fields[name] = value.trim();
105	      current.order.push(name);
106	      current.last = name;
107	      return;
108	    }
109	    if (/^\s{2,}\S/.test(line) && current.last) {
110	      current.fields[current.last] = `${current.fields[current.last]} ${line.trim()}`;
111	      return;
112	    }
113	    errors.push({ line: n, what: 'line is neither a "- **Field:** …" bullet nor an indented continuation of one' });
114	  });
115	  return { entries, errors };
116	}
117	
118	// live: the element stands (an empty file is an element whose history is not yet
119	// written); retired: its last entry retired it.
120	export function elementStatus(entries) {
121	  return entries.length && entries[entries.length - 1].kind === 'retired' ? 'retired' : 'live';
122	}
123	
124	// Faults of a parsed file beyond the line grammar: the first entry is `born`, and
125	// every mechanism-bearing kind carries Mechanism.
126	export function entryFaults(entries) {
127	  const out = [];
128	  entries.forEach((e, i) => {
129	    if (i === 0 && e.kind !== 'born') out.push({ line: e.line, what: `the first entry is "${e.kind}", and a file with entries opens with born` });
130	    if (MECHANISM_KINDS.includes(e.kind) && !('Mechanism' in e.fields)) out.push({ line: e.line, what: `a ${e.kind} entry carries no Mechanism` });
131	  });
132	  return out;
133	}
