1	// usage-review's own two terms.
2	//
3	// Neither is expressible in the built-in vocabulary: the movement conditions read
4	// the project's commits, issues, pull requests and captures, and this review's
5	// trigger is neither - it is the FOLD having moved, which is machinery, and the
6	// window holding enough sessions to say anything at all. Both read files the
7	// checkout already carries, so they cost no API call on a term asked every tick.
8	import { readFileSync } from 'node:fs';
9	import { join } from 'node:path';
10	import { readUsageFile, USAGE_PATH } from './read-record.mjs';
11	import { REVIEW_PATH } from './report.mjs';
12	
13	const repoRoot = () => process.env.CLAUDINITE_REPO_ROOT || process.cwd();
14	
15	const foldedThrough = (root) => readUsageFile(root)?.foldedThrough ?? null;
16	
17	const reviewedThrough = (root) => {
18	  try { return JSON.parse(readFileSync(join(root, REVIEW_PATH), 'utf8')).window?.to ?? null; }
19	  catch { return null; }
20	};
21	
22	// The sessions the fold carries for the trailing window - the denominator every
23	// rate rule divides by. Under ten, a rate says more about the window than about the
24	// subject, so the review declines rather than publishing findings nobody should act
25	// on.
26	export function windowSessions(root, days = 28) {
27	  const file = readUsageFile(root);
28	  if (!file?.days) return 0;
29	  const fields = file.fields?.day ?? [];
30	  const at = fields.indexOf('sessions');
...
40	  // The fold's watermark against the review's own. A review whose window already
41	  // ends where the fold does has read everything there is, and running it again
42	  // would recompute the same answer and deliver a byte-identical file.
43	  'fold-moved-since-review': {
44	    signals: [],
45	    holds() {
46	      const root = repoRoot();
47	      const fold = foldedThrough(root);
48	      if (!fold) return { holds: false, reason: `no ${USAGE_PATH} yet - there is no record to review` };
49	      const reviewed = reviewedThrough(root);
50	      if (!reviewed) return { holds: true, reason: `folded through ${fold} and never reviewed` };
51	      return fold > reviewed
52	        ? { holds: true, reason: `folded through ${fold}, reviewed through ${reviewed}: there are days the review has not read` }
53	        : { holds: false, reason: `reviewed through ${reviewed}, and the fold has not moved past it` };
54	    },
55	  },
56

