  if (m.usage.expect === 'judgment' && triggers > 0) { console.log('JUDGMENT, BUT HAS A TRIGGER', f); bad++; }
}
console.log(files.length, 'skills;', JSON.stringify(counts), '; problems:', bad);
" 2>&1 | tail -8

