const SKILL_DOC = /(^|\/)packs\/[^/]+\/skills\/[^/]+\/SKILL\.md$/;

const EXPECTS = frontmatter.EXPECTS ?? ['adoption', 'routine', 'triggered', 'rare'];
const canRead = () => typeof frontmatter.usageOf === 'function' && typeof frontmatter.parseFrontmatter === 'function';

const rule = {
