53	    const head = { exists: (p) => work.exists(p), read: (p) => work.read(p), listDir: (p) => listFrom(headFiles, p) };
54	    const baseFiles = [...new Set([...work.tracked, ...deleted])].filter((p) => work.readBase(p) !== null);
55	    const base = { exists: (p) => work.readBase(p) !== null, read: (p) => work.readBase(p), listDir: (p) => listFrom(baseFiles, p) };
